-- Class notes synopsis batch 2: Andrographis, Angelica, Arnica, Artichoke, Asafetida, Ashwagandha, Astragalus, Bacopa, Barberry, Basil

UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>Andrographis</strong> is an <strong>anti-inflammatory</strong>, <strong>antioxidant</strong>, <strong>adaptogen</strong>, <strong>hypoglycemic</strong>, and <strong>cardioprotective</strong> herb specific for <strong>liver congestion</strong> with fat intolerance and sluggish liver; indicated in <strong>arthritis</strong> and <strong>type 2 diabetes</strong>. Take with a tissue moistener like marshmallow glycerite. Dose: tincture 1 ml 3x/day. Also used for <strong>tick bite</strong> support - <strong>antimicrobial</strong> and <strong>antiviral</strong> after tick exposure, paired with <strong>Astragalus</strong> for immune support - and as a <strong>nervine</strong>/<strong>adaptogen</strong> for nervous system support in <strong>food sensitivity</strong> context. <strong>NOT for use in pregnancy or when trying to conceive.</strong>$$ WHERE common_name = 'Andrographis';

UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>Angelica</strong> (A. archangelica) is a <strong>warming bitter</strong>, mild <strong>nervine</strong>, and <strong>hormone-balancing</strong> herb used in 30 ml portions in formulas; as a <strong>digestive bitter</strong> it serves as a functional <strong>digestive stimulant</strong> for <strong>upper GI deficiency</strong> and appears in all-purpose bitter formulas. Respiratorily, it addresses <strong>spasmodic cough</strong> and <strong>asthma</strong> - breaking the feedback loop where coughing triggers more bronchial spasm - and serves as a <strong>relaxing expectorant</strong> and <strong>bronchodilator</strong> in antispasmodic formulas.$$ WHERE common_name = 'Angelica';

UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>Arnica</strong> flowers oil is excellent for <strong>strains</strong>, <strong>sprains</strong>, and <strong>bruises</strong>; used in salve with <strong>Frankincense</strong> for topical <strong>joint inflammation</strong> treatment. Note: high-quality flowers are hard to find.$$ WHERE common_name = 'Arnica';

UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>Artichoke</strong> leaf is a <strong>cooling</strong>, <strong>drying</strong>, <strong>bitter</strong>, and <strong>hepatic</strong> herb - described as "subtle" - used for <strong>digestive</strong> support; it rekindles digestive fire and is taken before mealtime as a bitter (alongside dandelion root or leaf). Indicated for hot constitution. Used for <strong>perimenopause</strong> digestive support alongside blue vervain, orange peel, and gentian; specific for <strong>nausea</strong> and <strong>bloating</strong> before meals in post-menopausal cases. Appears in all-purpose bitter formulas and alongside mullein for <strong>liver</strong> support and hydration.$$ WHERE common_name = 'Artichoke';

UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>Asafetida</strong> is an aromatic, pungent spice with <strong>sedative</strong>, <strong>antiviral</strong>, <strong>nervine</strong>, <strong>anti-inflammatory</strong>, and <strong>anticarcinogenic</strong> properties - said to inhibit, mitigate, prevent, and help cure <strong>cancer</strong>. Historically used in the American South (post-slavery era) for <strong>asthma</strong> and <strong>colic</strong>, administered as a tincture or worn raw around the neck. Listed among Black Herbal <strong>cardiovascular</strong> herbs for its antiviral properties ("warding off viral load"). Used as a <strong>nervine</strong> to calm and reduce <strong>pain</strong> in early-stage cancer formulas, for <strong>digestive</strong> support in cancer care, and for cardiovascular nervine support alongside oat straw/oat tops.$$ WHERE common_name = 'Asafetida';

UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>Ashwagandha</strong> is a <strong>warming</strong>, <strong>moistening</strong> <strong>adaptogen</strong> and <strong>nervine</strong> - a yang tonic in Ayurveda and member of the nightshade family - that regulates the <strong>HPA axis</strong>, stimulates <strong>metabolism</strong>, increases vitality and blood flow; indicated for pale, slow, weak, and deficient constitutions; for <strong>nervous exhaustion</strong>, <strong>anemia</strong>, emotional depletion, burnout, grief, sadness, and forgetfulness from frazzlement. Best as a fluid extract in milk (1/2 tsp powder or 15-30 drops); night formula: milk simmered with cinnamon, cardamom, and nutmeg. Specific for <strong>hypothyroidism</strong> - foggy, forgetful, slow transit time, depleted picture; supports thyroid function and HPA axis; indicated for thyroid-related <strong>depression</strong>; used in adaptogen/nervine tinctures for <strong>thyroid</strong>/<strong>Hashimoto's</strong> (with milky oats and licorice) and in absorption tinctures (with tulsi, schisandra, milk thistle, rosemary). A key herb in <strong>cancer</strong> care; <strong>antifibrotic</strong> (with white peony and astragalus). Supports <strong>blood sugar</strong> dysregulation and <strong>sex hormone</strong> regulation - yang tonic for masculine energy, increases sperm motility, reduces stress hormones, reduces cortisol conversion to increase <strong>testosterone</strong>; cycle 1-3 months. In sleep tincture with passionflower - described as a "cozy bathrobe," grounding but not directly sleep-inducing. For <strong>gut inflammation</strong> with marshmallow root and cinnamon; blood-building for cold constitution; <strong>adaptogen</strong>/<strong>nervine</strong> for <strong>ADHD</strong>, <strong>anxiety</strong>, and <strong>cognitive decline</strong> associated with <strong>hypertension</strong>; supports endurance and physical exercise tolerance. <strong>Caution: can cause irritability and aggravation in some people - switch to a different adaptogen if this occurs. Not for hot/wet constitution.</strong>$$ WHERE common_name = 'Ashwagandha';

UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>Astragalus</strong> (A. membranaceus) is a <strong>sweet</strong>, <strong>warming</strong>, <strong>moistening</strong> <strong>adaptogen</strong> that nourishes and builds tissues via polysaccharides and saponins; actions include <strong>immune amphoteric</strong>, <strong>cardiac tonic</strong>, <strong>diuretic</strong>, <strong>nephroprotective</strong>, <strong>hepatoprotective</strong>, <strong>circulation-enhancing</strong>, <strong>antioxidant</strong>, <strong>antifibrotic</strong> (with white peony and ashwagandha), <strong>anti-inflammatory</strong>, and <strong>restorative tonic</strong>; it induces apoptosis (eliminating aging and dead cells) and supports innate immunity and <strong>lymph</strong>/immune deficiency. Polysaccharides are the primary constituent class responsible for immune-tonic activity and improve <strong>insulin sensitivity</strong>, inhibiting insulin resistance. The primary <strong>pulmonary trophorestorative</strong> and most-used herb in <strong>asthma</strong>; dosing: 2-4 mL (~80 drops). Used in TCM for "wasting and thirsting syndrome" (3 Ps: polyuria, polyphagia, polydipsia); TCM formula: 5 parts Dang Gui to 1 part Astragalus for insulin sensitivity. Needs to be decocted - 4 hours (Instant Pot). Dose: decoction 2 tsp:12 oz water; tincture 1-3 ml 3x/day. Dosing principle: acute - frequent and high therapeutic range; chronic/tonic - medium-low and consistent. For <strong>fertility</strong>: protects from oxidative stress, supports sperm motility and semen quality, hormone modulating via isoflavones and saponin triterpenes; in Fertili-Tea and Legume Tea for Fertility (suggest both partners drink); in inositol-rich blend for <strong>PMOS</strong> (with licorice, red clover, alfalfa, kudzu). For <strong>post-menopausal</strong> dryness and burnout edge: moistening adaptogen; nourishing foundation when ginseng would be premature. For <strong>thyroid</strong> health - immune modulating and moistening adaptogen for dry tissues. Liver <strong>alterative</strong> for hot constitution; in liver tea formula (2P burdock, 2P astragalus, 1P dandelion, 1P orange peel, 1P fennel, 1P licorice). Chronic immune support for <strong>diarrhea</strong> (with reishi); in adaptogen/immune tonic protocol with reishi and schisandra; for <strong>eczema</strong> and <strong>psoriasis</strong>; <strong>tick bite</strong> immune support (with andrographis); in oxymel with nettle (3 oz nettle, 1 oz astragalus); 2 sticks in herbal broth; for <strong>poor circulation</strong>, slow <strong>digestion</strong>, <strong>constipation</strong>, low immunity, and stagnation; for <strong>anxiety</strong>; for prebiotic support (limit complexity in therapy). <strong>CAUTION: contraindicated when acutely sick - can drive infection deeper into tissues; so potent in moistening it can push to dampness. Aggravates damp conditions and fungal infections (polysaccharides feed yeast). Can be vasodilating and cardiodepressive in excess - too much fluid in tissues, pounding heartbeat.</strong>$$ WHERE common_name = 'Astragalus';

UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>Bacopa</strong> is an Ayurvedic <strong>nootropic</strong> herb that supports <strong>memory</strong>, <strong>cognitive function</strong>, and <strong>focus</strong>; it calms <strong>neuroinflammation</strong>, reduces <strong>anxiety</strong>, reduces <strong>inflammation</strong>, and nourishes the <strong>nervous system</strong> and <strong>heart</strong>. Specific for <strong>thyroid-related depression</strong> and <strong>hypothyroidism</strong> - supports mood and memory affected by low thyroid. Also indicated for <strong>ADHD</strong>, <strong>brain fog</strong>, <strong>cognitive decline</strong>, <strong>blood sugar dysregulation</strong>, <strong>PCOS</strong> (in "Temple of Devotion" formula), and <strong>stress</strong> and sleep support. Oil with <strong>Bacopa</strong> and <strong>Ginkgo</strong> massaged into the head for cognitive support.$$ WHERE common_name = 'Bacopa';

UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>Barberry</strong> is a berberine-containing herb that increases <strong>insulin sensitivity</strong>, reduces <strong>triglycerides</strong>, and lowers <strong>leptin</strong>; a key herb for <strong>blood sugar dysregulation</strong> and support in <strong>perimenopause</strong> (alongside Oregon Grape Root). Stimulates digestive secretions for <strong>upper GI deficiency</strong> (Thompson's Standard Protocol). Also <strong>antimicrobial</strong> in wound wash.$$ WHERE common_name = 'Barberry';

UPDATE herbal.herbs SET class_notes_synopsis = $$<strong>Basil</strong> is a <strong>warming</strong> spice for cold and dry constitutions; a smaller source of Vitamin A and beta carotene. Basil hydrosol is a <strong>skin tonic</strong> and insect repellent. <strong>Caution: contains higher concentrations of estragole - linked to liver cancer and blood clotting.</strong>$$ WHERE common_name = 'Basil';
